"""Optional galactic-binary waveforms for :mod:`petra.match`, generated by GBGPU and whitened with LISAanalysistools.

Install the PyPI packages with ``pip install "petra-catalogs[match]"``; the LISAanalysistools ``dev`` stack (GBGPU
``dev``) is installed by hand following its README and is driven the same way. Both are imported only when
:func:`gbgpu_waveforms` is called, so ``import petra`` never loads them.
"""

import inspect
import logging
from collections.abc import Callable, Mapping
from typing import Any

import numpy as np

from petra.match import WaveformBank
from petra.utils import check_int

logger = logging.getLogger(__name__)

#: GBGPU's own order and units, as in the CDL1 example files: angles in radians, phi0 as e^{+i phi0}.
GBGPU_COLUMNS = {"amplitude": 0, "f0": 1, "fdot": 2, "fddot": 3, "phi0": 4, "iota": 5, "psi": 6, "lam": 7, "beta": 8}
#: The GBMCMC/LDC file order, as in ``lisa_example.feather``: fddot is 0 and phi0 is e^{-i phi0}.
GBMCMC_COLUMNS = {"f0": 0, "fdot": 1, "amplitude": 2, "lam": 3, "sin_beta": 4, "cos_iota": 5, "psi": 6, "phi0": 7}
#: erebor's GB sampler basis, as in its global-fit store: distance [kpc], f0 [mHz], chirp mass [Msun], phi0, cos(iota),
#: psi, the ICRS right ascension alpha, sin of the ICRS declination and the ratio r with fdot = (1 + r) fdot_GR; read
#: through :func:`erebor_to_gbgpu`.
EREBOR_COLUMNS = {"distance": 0, "f0": 1, "chirp_mass": 2, "phi0": 3, "cos_iota": 4, "psi": 5, "alpha": 6,
                  "sin_delta": 7, "fdot_astro_ratio": 8}


def erebor_to_gbgpu(params: np.ndarray) -> np.ndarray:
    """Map erebor's GB sampler basis (..., 9) (:data:`EREBOR_COLUMNS`) to the GBGPU inputs of the run that sampled it.

    The amplitude and fdot are erebor's own (its ``McDistFdotAstroQuad``): GBGPU's ``get_amplitude`` for two equal
    masses of chirp mass Mc, and ``get_fdot(f0, Mc) * (1 + r)``; fddot is 0. The sky angles stay ICRS, the run's frame
    (``lam`` = alpha, ``beta`` = arcsin(sin_delta)), so the waveforms need the run's ICRS orbits. phi0 stays as
    sampled: erebor negates it into the LDC e^{-i phi0} convention of its likelihood, which is GBGPU's e^{+i phi0} of
    the sampled value. An absent (all-NaN) row stays all-NaN, so a padded chain converts whole. Needs gbgpu.
    """
    from gbgpu.utils.utility import get_amplitude, get_fdot

    params = np.asarray(params, dtype=np.float64)
    f0, chirp_mass = params[..., 1] * 1e-3, params[..., 2]
    # get_chirp_mass(m, m) is m / 2^(1/5), so two masses of Mc * 2^(1/5) have chirp mass Mc.
    mass = chirp_mass * 2.0 ** 0.2
    out = np.empty(params.shape[:-1] + (9,))
    out[..., 0] = get_amplitude(mass, mass, f0, params[..., 0])
    out[..., 1] = f0
    # A copy: get_fdot scales its Mc argument in place.
    out[..., 2] = get_fdot(f=f0, Mc=chirp_mass.copy()) * (1.0 + params[..., 8])
    out[..., 3] = np.where(np.isnan(f0), np.nan, 0.0)
    out[..., 4] = params[..., 3]
    out[..., 5] = np.arccos(params[..., 4])
    out[..., 6] = params[..., 5]
    out[..., 7] = params[..., 6]
    out[..., 8] = np.arcsin(params[..., 7])
    return out


# Each preset: the columns read after the conversion, the phase convention and the conversion (None for none).
_PRESETS = {"gbgpu": (GBGPU_COLUMNS, "gbgpu", None), "gbmcmc": (GBMCMC_COLUMNS, "ldc", None),
            "erebor": (GBGPU_COLUMNS, "gbgpu", erebor_to_gbgpu)}
_RESERVED = {"T", "dt", "tdi2", "oversample", "flip_ref_phase", "force_backend"}


def gbgpu_waveforms(T: float, dt: float, *, convention: str = "gbgpu", tdi2: bool = False,
                    phase_convention: str | None = None, columns: Mapping[str, int] | None = None,
                    oversample: int = 1, backend: str = "cpu", gbgpu_options: Mapping[str, Any] | None = None,
                    run_options: Mapping[str, Any] | None = None,
                    batch_size: int | None = None) -> Callable[[np.ndarray], WaveformBank]:
    """Return a callable that turns (n, P) present chain rows into a bank of their whitened TDI A and E waveforms.

    ``convention="gbgpu"`` reads :data:`GBGPU_COLUMNS`, ``[A, f0 Hz, fdot Hz/s, fddot Hz/s^2, phi0, iota, psi, lam,
    beta]`` (``lam``, ``beta`` the sky longitude and latitude in the orbits' frame) with phi0 passed as stored.
    ``convention="gbmcmc"`` reads :data:`GBMCMC_COLUMNS`, ``[f0, fdot, A, lam, sin(beta), cos(iota), psi, phi0]``, in
    the LDC e^{-i phi0} convention. ``convention="erebor"`` reads erebor's sampler basis (:data:`EREBOR_COLUMNS`)
    and converts it with :func:`erebor_to_gbgpu`; its sky angles are ICRS and its phases are defined at the run's
    start, so it requires ``gbgpu_options`` with the run's orbits in the ICRS frame and its ``t0`` (the dev GBGPU).
    ``columns`` maps the names ``amplitude, f0, fdot, fddot, phi0, iota, psi, lam, beta`` (or ``cos_iota``, ``sin_beta`` in place of ``iota``, ``beta``) to column indices for other layouts; a
    missing fddot is 0. An "ldc" phase uses GBGPU's ``flip_ref_phase=True`` where it exists and negates phi0 otherwise.

    T, dt, tdi2 and the orbits must be those of the run that sampled the chain. The PyPI GBGPU uses analytic equal-arm
    orbits; the dev GBGPU requires an ``orbits`` and takes the run's own (and its start time ``t0``) through
    ``gbgpu_options``, which goes to ``GBGPU(...)`` unchanged, as ``run_options`` goes to ``run_wave(...)``. The PSD
    is lisatools' ``get_sensitivity`` with its defaults (the ``sangria`` noise model, no galactic foreground) for the
    A and E channels of the TDI generation in use.

    With `batch_size`, GBGPU makes the waveforms that many rows at a time, all on one bin count: ``run_options["N"]``
    if given, else GBGPU's own for the whole block (the largest over its rows). The bank is the one a single call
    makes, and GBGPU's working memory is that of one batch.

    Args:
        T: observation time in seconds.
        dt: sampling cadence in seconds.
        convention: column preset, "gbgpu", "gbmcmc" or "erebor".
        tdi2: second-generation TDI.
        phase_convention: "gbgpu" (e^{+i phi0}) or "ldc" (e^{-i phi0}); None takes the preset's.
        columns: column index of each parameter, overriding the preset.
        oversample: GBGPU's factor on the number of bins per waveform.
        backend: GBGPU's ``force_backend``.
        gbgpu_options: further keywords for the ``GBGPU`` constructor, such as ``orbits``.
        run_options: further keywords for ``GBGPU.run_wave``.
        batch_size: rows per GBGPU call, >= 1; None makes one call.

    Returns:
        the callable, for :func:`petra.match.refine_catalog`.

    Raises:
        ValueError: T or dt is not finite and positive, a convention is unknown, `columns` is given with the erebor
            preset, the erebor preset lacks ICRS orbits or t0, `batch_size` is not a positive integer, or an option
            is one petra sets.
        ImportError: gbgpu or lisatools is not installed, or the erebor preset meets a GBGPU without orbits and t0.
    """
    if not (np.isfinite(T) and T > 0 and np.isfinite(dt) and dt > 0):
        raise ValueError(f"T and dt must be finite and positive, in seconds, got T={T!r} and dt={dt!r}.")
    if convention not in _PRESETS:
        raise ValueError(f"convention must be 'gbgpu', 'gbmcmc' or 'erebor', got {convention!r}.")
    preset, default_phase, convert = _PRESETS[convention]
    if convert is not None and columns is not None:
        raise ValueError(f"columns cannot be combined with convention={convention!r}, which converts a fixed layout.")
    if batch_size is not None:
        batch_size = check_int("batch_size", batch_size)
    phase_convention = default_phase if phase_convention is None else phase_convention
    if phase_convention not in ("gbgpu", "ldc"):
        raise ValueError(f"phase_convention must be 'gbgpu', 'ldc' or None, got {phase_convention!r}.")
    gbgpu_options, run_options = dict(gbgpu_options or {}), dict(run_options or {})
    clash = _RESERVED & (gbgpu_options.keys() | run_options.keys())
    if clash:
        raise ValueError(f"gbgpu_options and run_options cannot set {sorted(clash)}, which petra sets itself.")
    columns = dict(preset if columns is None else columns)
    if convention == "erebor" and (getattr(gbgpu_options.get("orbits"), "frame", None) != "icrs"
                                   or gbgpu_options.get("t0") is None):
        raise ValueError(
            "convention='erebor' reads ICRS sky angles and parameters defined at the run's start, so it needs the "
            "run's own orbits in the ICRS frame and its start time: gbgpu_options={'orbits': L1Orbits(l1_file, "
            "frame='icrs'), 't0': t0}. Orbits in another frame, or none, put every source at the wrong sky position.")
    try:
        from gbgpu.gbgpu import GBGPU
        from lisatools import sensitivity
    except ImportError as error:
        raise ImportError(
            'The waveform match needs the optional extra: pip install "petra-catalogs[match]" (the PyPI gbgpu and '
            "lisaanalysistools). The LISAanalysistools dev stack is installed by hand following its README."
        ) from error

    if convention == "erebor" and not {"orbits", "t0"} <= set(inspect.signature(GBGPU).parameters):
        raise ImportError("convention='erebor' needs a GBGPU that takes the run's orbits and t0: the LISAanalysistools "
                          "dev stack (GBGPU dev), installed by hand following its README.")
    negate = phase_convention == "ldc"
    if "flip_ref_phase" in inspect.signature(GBGPU).parameters:
        gbgpu_options["flip_ref_phase"], negate = negate, False
    gb: Any = GBGPU(force_backend=backend, **gbgpu_options)
    names = ("A2TDISens", "E2TDISens") if tdi2 else ("A1TDISens", "E1TDISens")
    if not all(hasattr(sensitivity, name) for name in names):
        logger.warning("lisatools has no %s, so the TDI-2 waveforms are whitened with the TDI-1 PSDs.", names)
        names = ("A1TDISens", "E1TDISens")
    curves = [getattr(sensitivity, name) for name in names]
    width = len(EREBOR_COLUMNS) if convert is not None else 1 + max(columns.values())

    def generate(p: dict[str, np.ndarray], options: Mapping[str, Any]) -> WaveformBank:
        """Return the whitened A and E waveforms of the rows whose columns `p` holds, in one GBGPU call."""
        iota = p["iota"] if "iota" in p else np.arccos(p["cos_iota"])
        beta = p["beta"] if "beta" in p else np.arcsin(p["sin_beta"])
        phi0 = -p["phi0"] if negate else p["phi0"]
        gb.run_wave(p["amplitude"], p["f0"], p["fdot"], p.get("fddot", np.zeros(len(p["f0"]))), phi0, iota, p["psi"],
                    p["lam"], beta, T=T, dt=dt, tdi2=tdi2, oversample=oversample, **options)
        start = np.asarray(gb.start_inds, dtype=np.int64)
        df = float(getattr(gb, "df", 1 / T))
        channels = [np.asarray(gb.A, dtype=np.complex128), np.asarray(gb.E, dtype=np.complex128)]
        f = (start[:, None] + np.arange(channels[0].shape[1])) * df
        data = np.stack([h / np.sqrt(sensitivity.get_sensitivity(f, sens_fn=c)) for h, c in zip(channels, curves)], 1)
        return WaveformBank(start, data, df)

    def waveforms(params: np.ndarray) -> WaveformBank:
        """Return the whitened A and E waveforms of every row of `params`."""
        params = np.asarray(params, dtype=float)
        if params.ndim != 2 or params.shape[1] < width:
            raise ValueError(f"Expected an (n, >= {width}) array of present rows, got shape {params.shape}.")
        if params.shape[0] == 0:
            return WaveformBank(np.zeros(0, np.int64), np.zeros((0, 2, 0), np.complex128), 1 / T)
        if convert is not None:
            params = convert(params)
        p = {name: params[:, index] for name, index in columns.items()}
        n = len(params)
        if batch_size is None or n <= batch_size:
            return generate(p, run_options)
        options = dict(run_options)
        if options.get("N") is None:
            options["N"] = int(np.max(gb.special_get_N(p["amplitude"], p["f0"], T, oversample=oversample)))
        start = np.empty(n, dtype=np.int64)
        data = np.empty((n, 2, options["N"]), dtype=np.complex128)
        for begin in range(0, n, batch_size):
            part = slice(begin, begin + batch_size)
            bank = generate({name: value[part] for name, value in p.items()}, options)
            start[part], data[part] = bank.start, bank.data
        return WaveformBank(start, data, bank.df)

    return waveforms
